// AUTO-GENERATED by Bloxks — DO NOT EDIT. Regenerated on every build.
// The app's typography.
// iOS uses its native system font; Android loads files to avoid falling back to Roboto.
//
// HOW TO USE (mandatory):
//   import { FONTS, useAppFonts } from './zzz/fonts'
//   <Text style={[styles.title, FONTS.display.bold]}>Hello</Text>
//
// ⚠️ CRITICAL: React Native IGNORES `fontWeight` once a custom font is loaded.
// `{ fontWeight: '600' }` renders REGULAR. To get any weight you MUST spread the
// matching entry below. Never write `fontFamily` or `fontWeight` by hand.
import { Platform, type TextStyle } from 'react-native'
import { useFonts } from 'expo-font'
import { Ionicons } from '@expo/vector-icons'

export const FONT_PACK_ID = "system"
/** true when at least one platform loads font files, so `fontWeight` alone is not enough. */
export const FONT_CUSTOM = true

type FontSlots = { regular: TextStyle; semibold: TextStyle; bold: TextStyle }
type FontStyles = { display: FontSlots; text: FontSlots; mono: FontSlots }

/**
 * Font files to register on THIS platform. The KEY is the family name used by
 * `fontFamily` — it is arbitrary and identical across iOS, Android and the web
 * preview, because `Font.loadAsync` registers a family under the key you give it
 * and ignores the name baked into the file.
 */
export const FONT_SOURCES = Platform.select({
  ios: {},
  android: {
    "AppText-Regular": "https://bloxks.app/fonts/inter/Inter-Regular.ttf",
    "AppText-SemiBold": "https://bloxks.app/fonts/inter/Inter-SemiBold.ttf",
    "AppText-Bold": "https://bloxks.app/fonts/inter/Inter-Bold.ttf",
    "AppMono-Regular": "https://bloxks.app/fonts/jetbrains-mono/JetBrainsMono-Regular.ttf",
    "AppMono-SemiBold": "https://bloxks.app/fonts/jetbrains-mono/JetBrainsMono-SemiBold.ttf",
    "AppMono-Bold": "https://bloxks.app/fonts/jetbrains-mono/JetBrainsMono-Bold.ttf",
  },
  default: {},
})

const IOS_FONTS: FontStyles = {
  display: {
    regular: { fontWeight: "400" },
    semibold: { fontWeight: "600" },
    bold: { fontWeight: "700" },
  },
  text: {
    regular: { fontWeight: "400" },
    semibold: { fontWeight: "600" },
    bold: { fontWeight: "700" },
  },
  mono: {
    regular: { fontFamily: "Menlo", fontWeight: "400" },
    semibold: { fontFamily: "Menlo", fontWeight: "600" },
    bold: { fontFamily: "Menlo", fontWeight: "700" },
  },
}

const ANDROID_FONTS: FontStyles = {
  display: {
    regular: { fontFamily: "AppText-Regular" },
    semibold: { fontFamily: "AppText-SemiBold" },
    bold: { fontFamily: "AppText-Bold" },
  },
  text: {
    regular: { fontFamily: "AppText-Regular" },
    semibold: { fontFamily: "AppText-SemiBold" },
    bold: { fontFamily: "AppText-Bold" },
  },
  mono: {
    regular: { fontFamily: "AppMono-Regular" },
    semibold: { fontFamily: "AppMono-SemiBold" },
    bold: { fontFamily: "AppMono-Bold" },
  },
}

/**
 * Ready-to-spread text styles. Build hierarchy with fontSize + these entries,
 * never with `fontWeight`.
 *   display → titles and hero numbers
 *   text    → body, labels, buttons
 *   mono    → figures in tables, timers, counters
 */
export const FONTS: FontStyles = Platform.select({
  ios: IOS_FONTS,
  android: ANDROID_FONTS,
  default: IOS_FONTS,
}) as FontStyles

/**
 * Loads the fonts. Call it ONCE at the root of `App` and hold the first render
 * until it returns true, otherwise Android briefly renders in Roboto.
 * Returns true on error too: a font that fails to download must never leave the
 * user stuck on a blank screen.
 *
 * The icon font is loaded HERE too, on Android only — see ICON_FONT above for
 * why the source differs between a published app and the Expo Go preview.
 */
// Police d'icônes, ANDROID uniquement (iOS rend des SF Symbols natifs et n'en
// lit jamais un octet).
//
// Deux sources selon le contexte, et c'est VOULU :
//  • app publiée → le fichier fourni avec `@expo/vector-icons`, embarqué dans le
//    binaire : affichage immédiat, hors ligne, aucune requête au démarrage ;
//  • aperçu Expo Go (`__DEV__`) → une URL absolue, car sur ce chemin l'asset du
//    paquet laisse la famille DÉCLARÉE mais NON APPLIQUÉE par React Native, et
//    toutes les icônes s'affichent en carré (constaté sur un vrai Android).
const ICON_FONT = Platform.select<Record<string, string | number>>({
  android: __DEV__ ? { "ionicons": "https://bloxks.app/fonts/ionicons/Ionicons.ttf" } : Ionicons.font,
  default: {},
})

export function useAppFonts(): boolean {
  const [loaded, error] = useFonts({ ...ICON_FONT, ...FONT_SOURCES })
  return loaded || error != null
}
